// --- Inlined bare-mux transport wrapper (added to the raw ep082 core) --------------------
// Lets the K4q9p2Xv controller drive this ep082 build exactly like the L1bc transport:
// init() / meta() / request() / connect(). Mirrors the @mercuryworkshop/epoxy-transport
// wrapper. It reaches the core classes (Ep082Client, Ep082ClientOptions, Ep082Handlers) and
// the wasm init (k, the module's default export) directly, since they are declared
// above in this same module.
//
// Response headers are read from res.rawHeaders -- an object this build defines on the
// Response that keeps every value, including each individual Set-Cookie, instead of the
// Headers object folding them all into one. That raw list is what lets cookies survive a
// round trip (the reason this transport is rebuilt from source).
const ep082TransportOpts = [
  'wisp_v2',
  'udp_extension_required',
  'title_case_headers',
  'ws_title_case_headers',
  'wisp_ws_protocols',
  'redirect_limit',
  'header_limit',
  'buffer_size',
];

export class Ep082Transport {
  ready = false;
  client = null;

  constructor(options) {
    this.wisp = options.wisp;
    this.opts = options;
  }

  setopt(options, opt) {
    if (this.opts[opt] != null) options[opt] = this.opts[opt];
  }

  async init() {
    if (this.ready) return; // idempotent: safe whether the controller or caller invokes it
    await k();
    const options = new Ep082ClientOptions();
    options.user_agent = navigator.userAgent;
    ep082TransportOpts.forEach((x) => this.setopt(options, x));
    this.client = new Ep082Client(this.wisp, options);
    this.ready = true;
  }

  async meta() {}

  async request(remote, method, body, headers, signal) {
    if (body instanceof Blob) body = await body.arrayBuffer();

    const headersObj = {};
    for (const [key, value] of headers) headersObj[key] = value;

    const res = await this.client.fetch(remote.href, {
      method,
      body,
      headers: headersObj,
      redirect: 'manual',
    });

    // res.rawHeaders: { name: value | [value, ...] }. Array values (e.g. multiple
    // Set-Cookie) are flattened into the ordered [name, value] list bare-mux expects,
    // so every cookie survives instead of being collapsed into one header.
    const headersEntries = [];
    const raw = res.rawHeaders;
    if (raw) {
      for (const [key, val] of Object.entries(raw)) {
        if (Array.isArray(val)) {
          for (const v of val) headersEntries.push([key, v]);
        } else {
          headersEntries.push([key, val]);
        }
      }
    } else {
      // Fallback for a build without rawHeaders: at least recover folded Set-Cookie.
      res.headers.forEach((value, key) => headersEntries.push([key, value]));
      if (typeof res.headers.getSetCookie === 'function') {
        const cookies = res.headers.getSetCookie();
        if (cookies.length) {
          for (let i = headersEntries.length - 1; i >= 0; i--) {
            if (headersEntries[i][0].toLowerCase() === 'set-cookie') headersEntries.splice(i, 1);
          }
          for (const c of cookies) headersEntries.push(['set-cookie', c]);
        }
      }
    }

    return {
      body: res.body,
      headers: headersEntries,
      status: res.status,
      statusText: res.statusText,
    };
  }

  connect(url, protocols, requestHeaders, onopen, onmessage, onclose, onerror) {
    const handlers = new Ep082Handlers(
      // ep082 does not surface the server-selected protocol/extension
      () => onopen('', ''),
      // ep082 does not surface the close code/reason
      () => onclose(1000, 'Closed by remote'),
      onerror,
      (data) => (data instanceof Uint8Array ? onmessage(data.buffer) : onmessage(data)),
    );

    const headersObj = {};
    for (const [key, value] of requestHeaders) headersObj[key] = value;

    const ws = this.client.connect_websocket(handlers, url.href, protocols, headersObj);
    return [
      async (data) => {
        if (data instanceof Blob) data = await data.arrayBuffer();
        (await ws).send(data);
      },
      async (code, reason) => {
        (await ws).close(code, reason || '');
      },
    ];
  }
}
